void Solver::bump_var(int var, double coeff) {
    // Fast‑path: no bump needed.
    if (coeff == 0.0) return;

    // Global scaling factor to avoid costly full‑vector rescales.
    static double scale = 1.0;

    // Compute the increment adjusted for the current scale.
    double inc = var_inc * coeff;
    double inc_scaled = inc / scale;

    // Update the (scaled) activity of the variable.
    activity[var] += inc_scaled;

    // If the true activity would overflow, adjust the global scale
    // and the increment factor instead of iterating over all variables.
    if (activity[var] * scale > 1e100) {
        scale *= 1e-100;          // shrink all activities lazily
        var_inc *= 1e-100;        // keep the relative bump magnitude
        // No explicit loop over all variables is needed.
    }

    // Keep the VSIDS heap up‑to‑date.
    if (vsids.inHeap(var)) vsids.update(var);
}

